#include "opensim/server/http_route_registry.hpp"
#include "opensim/network/osd_json.hpp"
#include "opensim/network/osd_value.hpp"
#include <algorithm>
#include <iostream>
#include <map>
using namespace opensim;using network::Value;using server::HttpRouteRegistry;
std::string hex(std::string_view s){std::string r;for(unsigned char c:s){r+="0123456789abcdef"[c>>4];r+="0123456789abcdef"[c&15];}return r;}
std::string unhex(std::string_view s){std::string r;for(std::size_t i=0;i<s.size();i+=2)r+=static_cast<char>(std::stoi(std::string(s.substr(i,2)),nullptr,16));return r;}
using Name=HttpRouteRegistry::Name;
Name optional(const Value& v){if(v.contains("__route_string"))return unhex(network::osd_string(v.get("__route_string")));return v.kind==Value::Kind::Undefined?std::nullopt:Name(network::osd_string(v));}
struct Handler;struct Context{Value command;std::string trace;int failures=0;bool mutated=false;std::map<std::string,std::shared_ptr<Handler>> handlers;void log(const std::string& op,const std::string& label);};
struct Handler:server::CapabilityStreamHandler,server::CapabilitySimpleHandler{Context& ctx;std::string id;std::vector<Name> paths;Name verb;mutable std::size_t reads=0;Handler(Context& c,std::string label,std::vector<Name> p,Name method):ctx(c),id(std::move(label)),paths(std::move(p)),verb(std::move(method)){}Name path()const override{ctx.log("path",id);return paths.at(std::min(reads++,paths.size()-1));}std::string method()const override{return verb.value_or("");}Name http_method()const override{ctx.log("method",id);return verb;}network::HttpResponse handle(const network::HttpRequest&)override{return {};}};
struct Poll:services::CapabilityPollHandler{std::string id;explicit Poll(std::string label,Name path):id(std::move(label)){url=std::move(path);}};
void Context::log(const std::string& op,const std::string& label){trace+=op+":"+label+";";auto failure=network::osd_string(command.get("failure"));if((failure==op||failure==op+":"+label)&&++failures==(command.contains("fail_nth")?network::osd_integer(command.get("fail_nth")):1))throw std::runtime_error("injected");if(!mutated&&network::osd_string(command.get("mutation"))==op+":"+label){mutated=true;handlers["A"]=handlers.at("B");}}
template<class T>std::string label(const std::shared_ptr<T>& h){if(!h)return "-";if(auto stream=std::dynamic_pointer_cast<Handler>(h))return stream->id;return "?";}
template<>std::string label(const std::shared_ptr<services::CapabilityPollHandler>& h){return h?std::dynamic_pointer_cast<Poll>(h)->id:"-";}
std::string keys(std::vector<std::string> names){std::vector<std::string> encoded;for(const auto& n:names)encoded.push_back(hex(n));std::sort(encoded.begin(),encoded.end());std::string r;for(const auto& n:encoded)r+=n+",";return r;}
int main(){std::string line;while(std::getline(std::cin,line)){Context ctx{network::parse_osd_json(unhex(line))};HttpRouteRegistry routes;std::map<std::string,std::shared_ptr<Poll>> polls;for(auto name:{"A","B","C","S"}){const auto& spec=ctx.command.get(name);std::vector<Name> paths;for(const auto& value:spec.get("paths").array)paths.push_back(optional(value));if(paths.empty())paths.push_back(spec.contains("path")?optional(spec.get("path")):Name("/x"));ctx.handlers[name]=std::make_shared<Handler>(ctx,name,paths,spec.contains("method")?optional(spec.get("method")):Name("GET"));polls[name]=std::make_shared<Poll>(name,spec.contains("path")?optional(spec.get("path")):Name("/x"));}std::string results;
for(const auto& op:ctx.command.get("ops").array){auto method=network::osd_string(op.get("op"));auto h=op.contains("h")?(op.get("h").kind==Value::Kind::Undefined?nullptr:ctx.handlers.at(network::osd_string(op.get("h")))):ctx.handlers.at("A");auto p=op.contains("h")?(op.get("h").kind==Value::Kind::Undefined?nullptr:polls.at(network::osd_string(op.get("h")))):polls.at("A");Name path=op.contains("path")?optional(op.get("path")):Name("/x");Name verb=op.contains("method")?optional(op.get("method")):Name("GET");std::string value="OK";HttpRouteRegistry::Stream stream=ctx.handlers.at("S");HttpRouteRegistry::Simple simple=ctx.handlers.at("S");HttpRouteRegistry::Poll poll=polls.at("S");try{if(method=="add")routes.add_stream(h);else if(method=="generic")routes.add_generic_stream(h);else if(method=="simple")routes.add_simple(h,network::osd_boolean(op.get("variable")));else if(method=="poll")value=routes.add_poll(p)?"1":"0";else if(method=="poll_at")value=routes.add_poll(path,p)?"1":"0";else if(method=="poll_variable")value=routes.add_poll_variable(p)?"1":"0";else if(method=="remove")routes.remove_stream(verb,path);else if(method=="remove_key")routes.remove_stream(path);else if(method=="remove_simple")routes.remove_simple(path);else if(method=="remove_poll")routes.remove_poll(path);else if(method=="remove_poll_method")routes.remove_poll(verb,path);else if(method=="get")value=routes.try_stream(path,stream)?"1":"0";else if(method=="get_simple")value=routes.try_simple(path,simple)?"1":"0";else if(method=="get_poll")value=routes.try_poll(path,poll)?"1":"0";else if(method=="key")value=hex(HttpRouteRegistry::handler_key(verb,path));else if(method=="mutate_poll"){if(!p)throw std::runtime_error("null");p->url=path;}}catch(const std::exception&){value="EX";}if(method=="get")value+=":"+label(stream);else if(method=="get_simple")value+=":"+label(simple);else if(method=="get_poll")value+=":"+label(poll);results+=value+",";}
std::vector<std::string> entries;for(const auto& k:routes.stream_keys()){HttpRouteRegistry::Stream h;routes.try_stream(k,h);entries.push_back(hex(k)+":"+label(h));}std::sort(entries.begin(),entries.end());std::string normal;for(const auto& e:entries)normal+=e+",";std::cout<<results<<"|"<<hex(ctx.trace)<<"|"<<normal<<"|"<<keys(routes.simple_keys())<<"|"<<keys(routes.poll_keys())<<"|"<<label(routes.root_get())<<"\n";}}
